  assign cdec = {g2585[2], g2585[1], n2587}; assign cvalid = vp[32];
  reg fprev; always @(posedge clk) fprev <= fp[32];
  wire init_p = fp[32] | fprev;                 // first two coefficients start the two chains

  // accumulator: acc_in = init ? (1,0,0) : acc_out ; acc_out = HPC2(acc_in, b)  (two interleaved chains)
  wire [2:0] bsh = {g2585[2], g2585[1], n2587};
  wire [2:0] acc_out; wire [2:0] acc_in = init_p ? 3'b001 : acc_out;
  hpc2 uacc (.clk(clk), .a(acc_in), .b(bsh), .r(rnd[173:171]), .c(acc_out));
  reg [2:0] acc_last;
  always @(posedge clk) acc_last <= acc_out;
  hpc2 ufin (.clk(clk), .a(acc_last), .b(acc_out), .r(rnd[176:174]), .c(dec));

  reg [3:0] lastp; always @(posedge clk) lastp <= {lastp[2:0], lp[32]};
  assign dvalid = lastp[3];
endmodule
